RECOVERY_SOURCE = '"""Recover completed Model 11 outputs and Kaggle inputs without refitting."""\nfrom pathlib import Path\nimport json,hashlib,shutil,zipfile\n\nREQUIRED=(\'config.json\',\'baseline_models.joblib\',\'verifier.joblib\',\'calibrators.joblib\')\n\n\ndef recover_archives(roots,working):\n    """Recognize checkpoint ZIPs by content, including renamed uploaded files."""\n    archives=[]\n    for root in roots:\n        if root.exists():\n            archives.extend(path for path in root.rglob(\'*\') if path.is_file() and path.suffix.lower()==\'.zip\')\n    recovered=[]\n    for archive in archives:\n        try:\n            with zipfile.ZipFile(archive) as z:\n                if \'manifest.json\' not in z.namelist():continue\n                manifest=json.loads(z.read(\'manifest.json\'))\n                if manifest.get(\'format\')!=1 or not all(\'run/\'+name in manifest.get(\'files\',{}) for name in REQUIRED):continue\n                # Verify all payloads before exposing any checkpoint files.\n                for name,expected in manifest[\'files\'].items():\n                    parts=name.split(\'/\')\n                    if len(parts)!=2 or parts[0] not in (\'run\',\'code\') or parts[1] in (\'\',\'..\',\'.\') or \'\\\\\' in name or \':\' in name:\n                        raise ValueError(\'Unsafe checkpoint archive member\')\n                    if hashlib.sha256(z.read(name)).hexdigest()!=expected:raise ValueError(f\'Checkpoint checksum failed: {name}\')\n                key=hashlib.sha256(z.read(\'manifest.json\')).hexdigest()[:12]\n                run=working/f\'model11_restored_{key}\'\n                for name,expected in manifest[\'files\'].items():\n                    group,filename=name.split(\'/\')\n                    target=run/filename if group==\'run\' else run/\'saved_sources\'/filename\n                    if target.exists() and hashlib.sha256(target.read_bytes()).hexdigest()!=expected:\n                        raise ValueError(f\'Restore would overwrite another file: {target}\')\n                for name in manifest[\'files\']:\n                    group,filename=name.split(\'/\')\n                    target=run/filename if group==\'run\' else run/\'saved_sources\'/filename\n                    target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(z.read(name))\n                print(\'Restored checkpoint ZIP:\',archive,\'->\',run)\n                recovered.append(run)\n        except zipfile.BadZipFile:continue\n    return sorted(set(recovered))\n\n\ndef find_runs(roots):\n    complete=[];partial=[]\n    for root in roots:\n        if not root.exists():continue\n        for file in root.rglob(\'config.json\'):\n            try:cfg=json.loads(file.read_text())\n            except (OSError,ValueError):continue\n            if cfg.get(\'primary\')!=\'mlp_blend\':continue\n            missing=[name for name in REQUIRED if not (file.parent/name).is_file()]\n            if missing:partial.append((str(file.parent),missing))\n            else:complete.append(file.parent)\n    return sorted(set(complete)),partial\n\n\ndef prepare(sources,preferred=None,roots=None,working=Path(\'/kaggle/working\')):\n    roots=roots or [working,Path(\'/kaggle/input\')]\n    runs,partial=find_runs(roots)\n    if not runs:\n        recover_archives(roots,working)\n        runs,partial=find_runs(roots)\n    preferred=Path(preferred) if preferred is not None else None\n    if preferred in runs:selected=preferred\n    elif len(runs)==1:selected=runs[0]\n    elif not runs:\n        raise FileNotFoundError(\'No complete Model 11 checkpoints found in /kaggle/working or /kaggle/input. \'\n            \'Attach the saved OUTPUT of your completed training notebook via Kaggle Add Input, then rerun this cell. \'\n            \'If those checkpoint files were never saved, the metric table cannot recreate them and training must be rerun. \'\n            f\'Partial runs and missing files: {partial}. \'\n            f\'Attached input folders: {[str(path) for root in roots if root.exists() for path in root.iterdir() if path.is_dir()]}\')\n    else:raise ValueError(f\'Multiple completed runs found. Set OUTPUT to the intended folder and rerun: {runs}\')\n    print(\'Found completed checkpoints:\',selected)\n    output=selected\n    if not selected.is_relative_to(working):\n        output=working/\'model11_submission_from_saved\';output.mkdir(parents=True,exist_ok=True)\n        for name in list(REQUIRED)+[f.name for f in selected.glob(\'sift_mutual_*.npz\')]:\n            shutil.copy2(selected/name,output/name)\n        print(\'Copied checkpoints into writable folder:\',output)\n    config=json.loads((output/\'config.json\').read_text())\n    code=working/\'model11_submission_code\';code.mkdir(parents=True,exist_ok=True)\n    for name,text in sources.items():\n        expected=config[\'sources\'][name]\n        variants=[text.encode(),text.replace(\'\\n\',\'\\r\\n\').encode()]\n        chosen=next((raw for raw in variants if hashlib.sha256(raw).hexdigest()==expected),None)\n        if chosen is None:raise ValueError(f\'Training source differs for {name}; use the sources from that saved notebook version\')\n        (code/name).write_bytes(chosen)\n    input_root=Path(\'/kaggle/input\')\n    options=[file.parent for file in input_root.rglob(\'miewid_features.npy\')\n             if all((file.parent/name).exists() for name in (\'train.csv\',\'test.csv\',\'miewid_ids.csv\'))]\n    if len(options)!=1:raise ValueError(f\'Attach the competition feature data (one metadata folder expected): {options}\')\n    data=options[0];inputs=working/\'model11_submission_input\';inputs.mkdir(exist_ok=True)\n    for name in (\'train.csv\',\'test.csv\',\'miewid_ids.csv\',\'miewid_features.npy\'):\n        dest=inputs/name;target=data/name\n        if dest.is_symlink() and not dest.exists():dest.unlink()\n        if not dest.exists():dest.symlink_to(target)\n        if dest.resolve()!=target.resolve():raise ValueError(f\'Stale input link: {dest}\')\n    for split in (\'train\',\'test\'):\n        name=f\'sift_features_{split}.npz\'\n        nearby=[base/name for base in (data,data.parent,data.parent.parent) if (base/name).exists()]\n        options=nearby[:1] or list(input_root.rglob(name))\n        if len(options)!=1:raise ValueError(f\'Attach full competition SIFT input: {name}: {options}\')\n        target=options[0];dest=inputs/name\n        if dest.is_symlink() and not dest.exists():dest.unlink()\n        if not dest.exists():dest.symlink_to(target,target_is_directory=target.is_dir())\n        if dest.resolve()!=target.resolve():raise ValueError(f\'Stale SIFT link: {dest}\')\n    import pandas as pd\n    ids=set(pd.read_csv(inputs/\'test.csv\').id)\n    candidates=[data/\'sample_submission.csv\'] if (data/\'sample_submission.csv\').exists() else list(input_root.rglob(\'sample_submission.csv\'))\n    matches=[]\n    for file in candidates:\n        frame=pd.read_csv(file)\n        if \'id\' in frame and frame.id.is_unique and set(frame.id)==ids:matches.append(file)\n    if len(matches)!=1:raise ValueError(f\'Cannot locate an unambiguous sample submission: {matches}\')\n    return code,output,inputs,matches[0]\n'
TRAINING_SOURCES = {'dalvin_core.py': '"""Dalvin Model 3d functions; raw evidence can use a frozen nuisance projection."""\nimport os\nimport re\nimport cv2\nimport lightgbm as lgb\nimport numpy as np\nimport pandas as pd\nfrom multiprocessing import Pool\nfrom scipy import sparse\nfrom scipy.sparse.csgraph import connected_components\nfrom sklearn.decomposition import PCA\nfrom sklearn.discriminant_analysis import LinearDiscriminantAnalysis as LDA\nK=15\nNEIGHBOURS=150\nMATCH_RATIO=.85\nRANSAC_PX=15.\nSIFT_PULL=.05\nVIEWS=[\'left\',\'right\',\'front\',\'back\',\'frontleft\',\'frontright\',\'backleft\',\'backright\',\'up\',\'down\']\nFLANK=np.array([0,1,2,2,0,1,0,1,2,2])\nREGIMES=[None,(.95,111),(.99,89),(.9,67)]\nPARAMS=dict(objective=\'binary\',learning_rate=.05,num_leaves=31,min_child_samples=30,subsample=.8,subsample_freq=1,colsample_bytree=.8,n_estimators=400,verbose=-1,random_state=42,n_jobs=4)\nINDEX_COLS=re.compile(r\'^(nb|nw|sb|sw)\\d$\')\n\n\n\n\n\n\n\ndef unit(a):\n    return a / np.linalg.norm(a, axis=1, keepdims=True)\n\n\ndef embed(gallery, labels, queries):\n    pca = PCA(min(384, gallery.shape[1], len(gallery) + len(queries) - 1), random_state=0).fit(np.r_[gallery, queries])      # unsupervised, sees the queries too\n    lda = LDA(solver="eigen", shrinkage=0.3).fit(pca.transform(gallery), labels)\n    project = lambda a: unit(lda.transform(pca.transform(a)))\n    return project(gallery), project(queries)\n\n\ndef per_identity(sim, inv, n):\n    """Per query: max and mean-of-top-2 similarity to each identity\'s gallery images."""\n    best, top2 = np.empty((sim.shape[0], n)), np.empty((sim.shape[0], n))\n    for j in range(n):\n        s = sim[:, inv == j]\n        best[:, j], top2[:, j] = s.max(1), np.sort(s, 1)[:, -2:].mean(1)\n    return best, top2\n\n\ndef species_features(gi, qi, sp):\n    """Query frame and (query, candidate) frame for one species; gi/qi are global image indices."""\n    Rg, Rq, yg, vg, vq = X[gi], X[qi], Y[gi], VIEW[gi], VIEW[qi]\n    Lg, Lq = embed(Rg, yg, Rq)\n    Rg, Rq = NX[gi], NX[qi]  # Frozen nuisance representation for raw evidence only.\n    ids, inv = np.unique(yg, return_inverse=True)\n    n, nq = len(ids), len(qi)\n    sim_l, sim_r = Lq @ Lg.T, Rq @ Rg.T\n    lda1, lda2 = per_identity(sim_l, inv, n)\n    raw1, raw2 = per_identity(sim_r, inv, n)\n    centroid = unit(np.stack([Lg[inv == j].mean(0) for j in range(n)]))\n    cen = Lq @ centroid.T\n    inl_g, good_g = INL[qi][:, gi].toarray().astype(np.float32), GOOD[qi][:, gi].toarray().astype(np.float32)\n    sift1, sift2 = per_identity(inl_g, inv, n)\n    good1, _ = per_identity(good_g, inv, n)\n    support = (inl_g >= 7).astype(np.float32) @ np.eye(n, dtype=np.float32)[inv]     # gallery images confirmed per identity\n    same_view = np.full((nq, n), np.nan)\n    for j in range(n):\n        for v in np.unique(vq):\n            cols = np.where((inv == j) & (vg == v))[0]\n            if len(cols):\n                same_view[vq == v, j] = sim_l[np.ix_(vq == v, cols)].max(1)\n    # viewpoint coverage: flanks of one animal look different, so unseen sides cannot be matched\n    by_view = np.stack([np.bincount(inv[vg == v], minlength=n) for v in range(len(VIEWS))], 1)\n    by_flank = np.stack([by_view[:, FLANK == f].sum(1) for f in range(3)], 1)\n    seen = vq >= 0\n    n_view = np.where(seen[:, None], by_view[:, vq.clip(0)].T, np.nan)\n    n_flank = np.where(seen[:, None], by_flank[:, FLANK[vq.clip(0)]].T, np.nan)\n    # transductive: neighbours among the queries themselves\n    qq_r, qq_l, qq_s = Rq @ Rq.T, Lq @ Lq.T, INL[qi][:, qi].toarray().astype(np.float32)\n    np.fill_diagonal(qq_r, -1), np.fill_diagonal(qq_l, -1)\n    nb, sb = np.argsort(-qq_l, 1)[:, :5], np.argsort(-qq_s, 1)[:, :5]\n    nbs, sbs = np.take_along_axis(qq_l, nb, 1), np.take_along_axis(qq_s, sb, 1)\n    t_l = np.take_along_axis(lda1, np.argsort(-lda1, 1)[:, :3], 1)\n    t_r = -np.sort(-raw1, 1)[:, :3]\n    t_s = -np.sort(-sift1, 1)[:, :3]\n    g_top = -np.sort(-sim_l, 1)\n    q = pd.DataFrame({\n        "sp": int(sp == "hyena"), "view": vq, "ng": len(gi),\n        "l1": t_l[:, 0], "l2": t_l[:, 1], "l3": t_l[:, 2], "r1": t_r[:, 0], "r2": t_r[:, 1], "r3": t_r[:, 2],\n        "lm12": t_l[:, 0] - t_l[:, 1], "rm12": t_r[:, 0] - t_r[:, 1],\n        "gd5": g_top[:, :5].mean(1), "gd20": g_top[:, :20].mean(1),\n        "qq1": nbs[:, 0], "qq3": nbs[:, :3].mean(1), "qq5": nbs.mean(1), "qqr1": qq_r.max(1),\n        "qn6": (qq_r > .6).sum(1), "qn7": (qq_r > .7).sum(1), "qn8": (qq_r > .8).sum(1),\n        "qq_minus_g": nbs[:, 0] - t_l[:, 0], "nb_g1": t_l[nb[:, 0], 0],\n        "s1": t_s[:, 0], "s2": t_s[:, 1], "s3": t_s[:, 2], "sg": good_g.max(1),\n        "qs1": sbs[:, 0], "qs3": sbs[:, :3].mean(1), "qsn10": (qq_s >= 10).sum(1), "qsn20": (qq_s >= 20).sum(1),\n        "qs_minus_s": sbs[:, 0] - t_s[:, 0], "nbs_s1": t_s[sb[:, 0], 0],\n    })\n    for k in range(5):\n        q[f"nb{k}"], q[f"nw{k}"], q[f"sb{k}"], q[f"sw{k}"] = nb[:, k], nbs[:, k], sb[:, k], sbs[:, k]\n    # candidates: best identities by embedding similarity, lightly boosted by SIFT evidence\n    cand = np.argsort(-(lda1 + SIFT_PULL * np.tanh(sift1 / 15)), 1)[:, :K]\n    r, c = np.repeat(np.arange(nq), K), cand.ravel()\n    nb_ev = np.max(np.minimum(nbs[:, :, None], np.stack([lda1[nb[:, k]] for k in range(5)], 1)), 1)\n    sb_ev = np.max(np.minimum(sbs[:, :, None], np.stack([sift1[sb[:, k]] for k in range(5)], 1)), 1)\n    rank_of = lambda m: (-m).argsort(1).argsort(1)[r, c]\n    cd = pd.DataFrame({\n        "q": r, "c": c, "rank": np.tile(np.arange(K), nq), "ident": ids[c],\n        "mxr": raw1[r, c], "m2r": raw2[r, c], "mxl": lda1[r, c], "m2l": lda2[r, c], "cl": cen[r, c],\n        "gapl": lda1[r, c] - t_l[r, 0], "gapr": raw1[r, c] - t_r[r, 0], "same": same_view[r, c],\n        "cnt": np.bincount(inv)[c], "nbev": nb_ev[r, c], "sbev": sb_ev[r, c],\n        "rk_r": rank_of(raw1), "rk_c": rank_of(cen), "rk_s": rank_of(sift1),\n        "n_view": n_view[r, c], "n_flank": n_flank[r, c], "support": support[r, c], "sx": sift1[r, c], "s2x": sift2[r, c], "gx": good1[r, c], "sgap": sift1[r, c] - t_s[r, 0],\n    })\n    return q, cd\n\n\ndef build_frames(gi, qi):\n    qs, cs, order, off = [], [], [], 0\n    for sp in ("hyena", "leopard"):\n        g, qq = gi[SP[gi] == sp], qi[SP[qi] == sp]\n        q, c = species_features(g, qq, sp)\n        c["q"] += off\n        q[[f"{p}{k}" for p in ("nb", "sb") for k in range(5)]] += off\n        qs.append(q), cs.append(c), order.append(qq)\n        off += len(qq)\n    return dict(q=pd.concat(qs, ignore_index=True), c=pd.concat(cs, ignore_index=True), order=np.concatenate(order))\n\n\ndef duplicate_groups(ix, link):\n    """Group images of one identity that are near-duplicates (same encounter); each image alone if link is None."""\n    if link is None:\n        return np.arange(len(ix))\n    edges = (X[ix] @ X[ix].T > link[0]) | (INL[ix][:, ix].toarray() >= link[1])\n    return connected_components(sparse.csr_matrix(edges))[1]\n\n\ndef columns(s):\n    qf = [c for c in s["q"].columns if c != "unk" and not INDEX_COLS.match(c)]\n    cf = [c for c in s["c"].columns if c not in ("q", "c", "ident", "y")]\n    return qf, cf\n\n\ndef candidate_matrix(s, qf, cf):\n    return pd.concat([s["c"][cf].reset_index(drop=True), s["q"].iloc[s["c"].q.to_numpy()][qf].reset_index(drop=True)], axis=1)\n\n\ndef fit(sims):\n    """new-individual detector, closed-set candidate scorer, and all-query candidate scorer."""\n    qf, cf = columns(sims[0])\n    known = lambda s: s["q"].unk.to_numpy()[s["c"].q.to_numpy()] == 0\n    cx = pd.concat([candidate_matrix(s, qf, cf) for s in sims])\n    cy = np.concatenate([s["c"].y.to_numpy() for s in sims])\n    ck = np.concatenate([known(s) for s in sims])\n    detector = lgb.LGBMClassifier(**{**PARAMS, "n_estimators": 300, "num_leaves": 15}).fit(\n        pd.concat([s["q"][qf] for s in sims]), np.concatenate([s["q"].unk.to_numpy() for s in sims]))\n    return detector, lgb.LGBMClassifier(**PARAMS).fit(cx[ck], cy[ck]), lgb.LGBMClassifier(**PARAMS).fit(cx, cy), (qf, cf)\n\n\ndef predict(models, s):\n    detector, closed, anyq, (qf, cf) = models\n    nq, cx = len(s["q"]), candidate_matrix(s, qf, cf)\n    p_new = detector.predict_proba(s["q"][qf])[:, 1]\n    raw = anyq.predict_proba(cx)[:, 1].reshape(nq, K)\n    within = closed.predict_proba(cx)[:, 1].reshape(nq, K)\n    within /= np.maximum(within.sum(1, keepdims=True), 1e-9)\n    return dict(pn=p_new, raw=raw, pc=within, pb=(p_new + np.clip(1 - raw.sum(1), 0, 1)) / 2)\n\n\ndef rank(s, r):\n    """Top-5 labels: P(new) vs (1 - P(new)) * P(identity | known)."""\n    nq = len(s["q"])\n    labels = np.concatenate([s["c"].ident.to_numpy(dtype=object).reshape(nq, K), np.full((nq, 1), "new_individual", dtype=object)], 1)\n    scores = np.concatenate([(1 - r["pb"])[:, None] * r["pc"], r["pb"][:, None]], 1)\n    return np.take_along_axis(labels, np.argsort(-scores, 1)[:, :5], 1)\n\n\ndef map5(preds, truth):\n    return np.mean([next((1 / (i + 1) for i, p in enumerate(row) if p == t), 0.0) for row, t in zip(preds, truth)])\n\n\ndef augment(s, r):\n    """Add the previous round\'s predictions for each query and for its nearest query neighbours."""\n    q, c, nq = s["q"].copy(), s["c"].copy(), len(s["q"])\n    codes = pd.factorize(c.ident)[0].reshape(nq, K)\n    q["r_pn"], q["r_pb"], q["r_rawsum"], q["r_rawmax"] = r["pn"], r["pb"], r["raw"].sum(1), r["raw"].max(1)\n    c["r_raw"], c["r_pc"] = r["raw"].ravel(), r["pc"].ravel()\n    for kind, weight, scale in (("nb", "nw", 1.0), ("sb", "sw", 30.0)):     # embedding / SIFT neighbours\n        evidence, support, pb, w, top = np.zeros((nq, K)), np.zeros((nq, K)), [], [], []\n        for k in range(5):\n            idx, sim = q[f"{kind}{k}"].to_numpy(), q[f"{weight}{k}"].to_numpy() / scale\n            wk = np.clip(sim - 0.4, 0, None) if kind == "nb" else np.clip(sim, 0, 1)\n            agree = ((codes[idx][:, None, :] == codes[:, :, None]) * r["raw"][idx][:, None, :]).sum(2)\n            evidence = np.maximum(evidence, np.minimum(agree, np.clip(sim, 0, 1)[:, None]))\n            support += wk[:, None] * agree\n            pb.append(r["pb"][idx]), w.append(wk), top.append(r["raw"][idx].max(1))\n        pb, w = np.stack(pb, 1), np.stack(w, 1)\n        q[f"{kind}_pb0"], q[f"{kind}_pbw"] = pb[:, 0], (pb * w).sum(1) / np.maximum(w.sum(1), 1e-6)\n        q[f"{kind}_pbmin"], q[f"{kind}_w"], q[f"{kind}_rm0"] = np.where(w > 0, pb, 1).min(1), w.sum(1), top[0]\n        c[f"r_{kind}ev"], c[f"r_{kind}sum"] = evidence.ravel(), support.ravel()\n    return dict(s, q=q, c=c)\n', 'data_protocol.py': '"""Data loading, role-local mutual SIFT and identity-disjoint episode helpers."""\nimport os\nimport hashlib\nfrom pathlib import Path\nfrom concurrent.futures import ThreadPoolExecutor\nfrom functools import lru_cache\nfrom threading import Lock\nimport numpy as np\nimport pandas as pd\nimport cv2\nfrom scipy import sparse\nimport dalvin_core as b\nNEW=\'new_individual\'\ndef find_sift(root, split):\n    """Kaggle mounts SIFT beside the metadata folder, sometimes as extracted NPZ directories."""\n    name = f"sift_features_{split}.npz"\n    for parent in (root, root.parent, root.parent.parent):\n        candidate = parent / name\n        if candidate.exists():\n            return candidate\n    raise FileNotFoundError(f"Cannot find {name} in {root} or its two parent directories. "\n                            "Attach the full projectwild3 competition input, including both SIFT folders.")\n\n\nclass SiftSource:\n    def __init__(self, path):\n        self.archive = None\n        self.files = {}\n        if path.is_file():\n            self.archive = np.load(path)\n        else:\n            for file in path.rglob("*.npy"):\n                if file.stem in self.files:\n                    raise ValueError(f"Duplicate SIFT key {file.stem} in {path}")\n                self.files[file.stem] = file\n            if not self.files:\n                raise ValueError(f"No extracted .npy SIFT arrays in {path}")\n\n    def __getitem__(self, key):\n        return self.archive[key] if self.archive is not None else np.load(self.files[key], allow_pickle=False)\n\n\ndef load_data(root):\n    train = pd.read_csv(root / "train.csv")\n    test = pd.read_csv(root / "test.csv")\n    ids = pd.read_csv(root / "miewid_ids.csv")\n    all_df = pd.concat([train, test.assign(identity=None)], ignore_index=True)\n    if not all_df.id.is_unique or not ids.id.is_unique:\n        raise ValueError("Duplicate image IDs")\n    for col in ("species", "viewpoint", "identity"):\n        if col not in all_df:\n            raise ValueError(f"Missing column: {col}")\n    if train.identity.isna().any() or not set(all_df.species) <= {"hyena", "leopard"}:\n        raise ValueError("Invalid identity/species metadata")\n    raw = np.load(root / "miewid_features.npy", mmap_mode="r")\n    if len(raw) != len(ids) or set(ids.id) != set(all_df.id):\n        raise ValueError("Feature ID mapping does not match metadata")\n    ix = pd.Index(ids.id).get_indexer(all_df.id)\n    X = np.asarray(raw[ix], dtype=np.float32)\n    if not np.isfinite(X).all() or np.any(np.linalg.norm(X, axis=1) == 0):\n        raise ValueError("Features contain nonfinite values or zero vectors")\n    b.X = b.unit(X)\n    b.IDS = all_df.id.to_numpy()\n    b.Y = all_df.identity.to_numpy(dtype=object)\n    b.SP = all_df.species.to_numpy()\n    b.VIEW = all_df.viewpoint.map({v: i for i, v in enumerate(b.VIEWS)}).fillna(-1).to_numpy(int)\n    return train, test, all_df\n\n\nclass SiftCache:\n    """Role-local neighbour selection; thread workers share lazily loaded descriptors."""\n    def __init__(self, root, out, workers, neighbours):\n        paths = [find_sift(root, s) for s in ("train", "test")]\n        print("SIFT sources:", *paths, sep="\\n", flush=True)\n        self.z = [SiftSource(path) for path in paths]\n        self.read_lock = Lock()\n        self.workers, self.neighbours = workers, neighbours\n        fingerprint = hashlib.sha256(b.IDS.tobytes() if b.IDS.dtype != object else "\\n".join(b.IDS).encode())\n        fingerprint.update(np.ascontiguousarray(b.X).tobytes())\n        self.path = out / ("sift_mutual_" + fingerprint.hexdigest()[:16] + ".npz")\n        self.done = {}\n        if self.path.exists():\n            with np.load(self.path) as z:\n                self.done = {tuple(p): tuple(v) for p, v in zip(z["pairs"], z["values"])}\n\n    @lru_cache(maxsize=1200)\n    def descriptors(self, i):\n        iid = b.IDS[i]\n        z = self.z[0 if iid.startswith("tr_") else 1]\n        # NpzFile\'s shared ZIP handle is not safe for concurrent reads.\n        with self.read_lock:\n            d = np.asarray(z[f"{iid}_desc"], dtype=np.float32)\n            xy = np.asarray(z[f"{iid}_xy"], dtype=np.float32)\n        if d.ndim != 2 or xy.shape != (len(d), 2):\n            raise ValueError(f"Malformed SIFT arrays for {iid}")\n        d = np.sqrt(d / np.maximum(d.sum(1, keepdims=True), 1))\n        return d, xy\n\n    def verify(self, pair):\n        a, c = pair\n        da, xa = self.descriptors(a)\n        dc, xc = self.descriptors(c)\n        if min(len(da), len(dc)) < 4:\n            return 0, 0\n        bf = cv2.BFMatcher()\n        back = np.array([m.trainIdx for m in bf.match(dc, da)])\n        matches = bf.knnMatch(da, dc, k=2)\n        good = [m[0] for m in matches if len(m) == 2 and m[0].distance < .85*m[1].distance\n                and back[m[0].trainIdx] == m[0].queryIdx]\n        if len(good) < 4:\n            return len(good), 0\n        # Local RNG seed per task. OpenCV RNG state is thread-local.\n        cv2.setRNGSeed(int((int(a)*100003 + int(c)) % (2**31-1)))\n        _, mask = cv2.estimateAffinePartial2D(\n            np.float32([xa[m.queryIdx] for m in good]),\n            np.float32([xc[m.trainIdx] for m in good]),\n            method=cv2.RANSAC, ransacReprojThreshold=15.)\n        return len(good), int(mask.sum()) if mask is not None else 0\n\n    def activate(self, indices):\n        wanted = set()\n        for sp in ("hyena", "leopard"):\n            ix = indices[b.SP[indices] == sp]\n            # Chunked similarities avoid allocating the full role x role matrix.\n            for start in range(0, len(ix), 256):\n                q = ix[start:start+256]\n                s = b.X[q] @ b.X[ix].T\n                s[np.arange(len(q)), np.arange(start, start+len(q))] = -np.inf\n                k = min(self.neighbours, len(ix)-1)\n                nb = np.argsort(-s, axis=1)[:, :k]\n                for a, row in zip(q, nb):\n                    wanted.update((min(int(a), int(c)), max(int(a), int(c))) for c in ix[row])\n        missing = sorted(wanted - self.done.keys())\n        print(f"SIFT: {len(wanted)} role-local pairs; {len(missing)} uncached", flush=True)\n        with ThreadPoolExecutor(max_workers=self.workers) as pool:\n            for j, (pair, value) in enumerate(zip(missing, pool.map(self.verify, missing)), 1):\n                self.done[pair] = value\n                if j % 5000 == 0:\n                    self.save()\n                    print(f"  verified {j}/{len(missing)}", flush=True)\n        self.save()\n        # Only expose requested pairs, even when cache contains other roles/test.\n        pp = np.array(sorted(wanted), dtype=int).reshape(-1, 2)\n        vv = np.array([self.done[tuple(p)] for p in pp]).reshape(-1, 2)\n        n = len(b.X)\n        def matrix(v):\n            a, c = pp.T\n            return sparse.coo_matrix((np.r_[v, v], (np.r_[a, c], np.r_[c, a])), shape=(n, n)).tocsr()\n        b.GOOD, b.INL = matrix(vv[:, 0]), matrix(vv[:, 1])\n\n    def save(self):\n        """Persist completed verifications atomically so interrupted runs can resume."""\n        pairs = sorted(self.done)\n        tmp = self.path.with_suffix(".tmp.npz")\n        np.savez_compressed(tmp, pairs=np.array(pairs, dtype=np.int64).reshape(-1, 2),\n                            values=np.array([self.done[p] for p in pairs]).reshape(-1, 2))\n        os.replace(tmp, self.path)\n\n\ndef allocate_roles(train, rounds, seed):\n    rng = np.random.default_rng(seed)\n    roles = {f"stage{i+1}": [] for i in range(rounds)} | {"calibration": [], "validation": []}\n    for sp in ("hyena", "leopard"):\n        names = np.array(sorted(train.loc[train.species == sp, "identity"].unique()))\n        rng.shuffle(names)\n        n = max(1, int(round(.2*len(names))))\n        roles["validation"].extend(names[:n])\n        roles["calibration"].extend(names[n:2*n])\n        for i, block in enumerate(np.array_split(names[2*n:], rounds)):\n            roles[f"stage{i+1}"].extend(block)\n    sets = [set(v) for v in roles.values()]\n    assert all(not a & c for i, a in enumerate(sets) for c in sets[i+1:])\n    return {k: np.flatnonzero(train.identity.isin(v).to_numpy()) for k, v in roles.items()}\n\n\ndef split_episode(indices, seed, cap=32, link=(.95, 100)):\n    """Unknown identities absent from gallery; known-query duplicate groups kept whole."""\n    rng = np.random.default_rng(seed)\n    gallery, known, unknown = [], [], []\n    for sp in ("hyena", "leopard"):\n        ix = indices[b.SP[indices] == sp]\n        names = np.unique(b.Y[ix])\n        rng.shuffle(names)\n        nu = max(1, int(round(rng.uniform(.2, .35)*len(names))))\n        unseen = set(names[:nu])\n        for name in names:\n            rows = ix[b.Y[ix] == name].copy()\n            rng.shuffle(rows)\n            if name in unseen:\n                unknown.extend(rows[:cap])\n                continue\n            held = []\n            groups = b.duplicate_groups(rows, link)\n            target = min(max(1, int(round(.35*len(rows)))), cap)\n            for c in rng.permutation(np.unique(groups)):\n                members = rows[groups == c].tolist()\n                if len(held) < target and len(held)+len(members) < len(rows):\n                    held.extend(members)\n            # Never truncate a duplicate group after selecting it.\n            known.extend(held)\n            gallery.extend(i for i in rows if i not in set(held))\n    gi, qi = np.array(gallery, dtype=int), np.array(known+unknown, dtype=int)\n    if not len(known) or not len(unknown):\n        raise ValueError("Episode lacks known/unknown queries; use a larger role or different seed")\n    for sp in ("hyena", "leopard"):\n        if len(np.unique(b.Y[gi[b.SP[gi] == sp]])) < b.K or np.sum(b.SP[qi] == sp) < 6:\n            raise ValueError("Too few identities/queries per species; reduce --rounds or --candidates")\n    assert not set(b.Y[unknown]) & set(b.Y[gi])\n    assert set(b.Y[known]) <= set(b.Y[gi])\n    return gi, qi, np.where(np.isin(qi, unknown), NEW, b.Y[qi])\n\n\ndef frame(gi, qi, truth=None):\n    s = b.build_frames(gi, qi)\n    if truth is not None:\n        lookup = dict(zip(qi, truth))\n        s["truth"] = np.array([lookup[i] for i in s["order"]])\n        s["q"]["unk"] = (s["truth"] == NEW).astype(int)\n        s["c"]["y"] = (s["c"].ident.to_numpy() == s["truth"][s["c"].q.to_numpy()]).astype(int)\n    return s\n\n\ndef through_stack(s, models):\n    for i, m in enumerate(models):\n        r = b.predict(m, s)\n        if i < len(models)-1:\n            s = b.augment(s, r)\n    return s, r\n', 'verifier.py': '"""Full-vector pair MLP and gallery-aware unknown calibration. No raw images."""\nimport copy\nimport numpy as np\nfrom scipy.sparse import csr_matrix\nfrom scipy.sparse.csgraph import connected_components\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.metrics import log_loss, roc_auc_score\n\n\ndef pair_features(x, a, c):\n    """Symmetric, full 2152-D descriptor interactions, without identity inputs."""\n    return np.c_[np.abs(x[a]-x[c]),x[a]*x[c],np.sum(x[a]*x[c],axis=1)].astype(np.float32)\n\n\ndef sample_pairs(x,y,sp,indices,seed,max_pairs=24000):\n    rng=np.random.default_rng(seed); pairs=[]; labels=[]\n    for species in (\'hyena\',\'leopard\'):\n        ix=indices[sp[indices]==species]; sim=x[ix]@x[ix].T\n        groups=np.zeros(len(ix),int); offset=0\n        for name in np.unique(y[ix]):\n            loc=np.flatnonzero(y[ix]==name)\n            _,gg=connected_components(csr_matrix(sim[np.ix_(loc,loc)]>=.97),directed=False)\n            groups[loc]=gg+offset; offset+=gg.max()+1\n        # Cap anchor appearances per identity so large identities do not dominate.\n        anchors=[]\n        for name in np.unique(y[ix]):\n            loc=np.flatnonzero(y[ix]==name)\n            anchors.extend(rng.choice(loc,min(24,len(loc)),replace=False))\n        for j in anchors:\n            pos=np.flatnonzero((y[ix]==y[ix[j]])&(groups!=groups[j]))\n            neg=np.flatnonzero(y[ix]!=y[ix[j]])\n            if not len(pos) or not len(neg):continue\n            hard=neg[np.argsort(-sim[j,neg])[:30]]\n            for _ in range(2):\n                for candidate,label in ((rng.choice(pos),1),(rng.choice(hard),0),(rng.choice(neg),0)):\n                    pairs.append((ix[j],ix[candidate])); labels.append(label)\n    if not pairs:raise ValueError(\'No usable training pairs\')\n    pairs=np.asarray(pairs); labels=np.asarray(labels)\n    # Deduplicate unordered pairs before sampling to avoid duplicate weights.\n    pairs=np.sort(pairs,axis=1); _,keep=np.unique(pairs,axis=0,return_index=True)\n    keep=rng.permutation(keep)[:max_pairs]\n    if len(np.unique(labels[keep]))!=2:raise ValueError(\'Pair classes missing\')\n    return pairs[keep],labels[keep]\n\n\ndef fit_verifier(x,y,sp,indices,seed=2052,epochs=40,max_pairs=24000):\n    rng=np.random.default_rng(seed); fit=[]; stop=[]\n    for species in (\'hyena\',\'leopard\'):\n        names=np.unique(y[indices[sp[indices]==species]]); rng.shuffle(names)\n        n=max(2,round(.2*len(names)))\n        stop.extend(indices[(sp[indices]==species)&np.isin(y[indices],names[:n])])\n        fit.extend(indices[(sp[indices]==species)&np.isin(y[indices],names[n:])])\n    fit=np.asarray(fit); stop=np.asarray(stop)\n    assert not set(y[fit]) & set(y[stop])\n    fp,fy=sample_pairs(x,y,sp,fit,seed,max_pairs)\n    ep,ey=sample_pairs(x,y,sp,stop,seed+1,min(8000,max_pairs))\n    scaler=StandardScaler().fit(pair_features(x,*fp.T))\n    transform=lambda pairs:np.clip(scaler.transform(pair_features(x,*pairs.T)),-6,6).astype(np.float32)\n    xx,ee=transform(fp),transform(ep)\n    net=MLPClassifier(hidden_layer_sizes=(32,16),alpha=1.,batch_size=256,\n        learning_rate_init=.0003,random_state=seed,early_stopping=False)\n    best=None; best_loss=np.inf; stale=0; history=[]\n    for epoch in range(1,epochs+1):\n        order=rng.permutation(len(fy)); net.partial_fit(xx[order],fy[order],classes=[0,1])\n        pr=net.predict_proba(ee)[:,1]; loss=log_loss(ey,pr,labels=[0,1])\n        history.append(dict(epoch=epoch,stop_logloss=float(loss),stop_auc=float(roc_auc_score(ey,pr))))\n        print(\'MLP epoch\',epoch,\'identity-stop loss\',round(loss,5),flush=True)\n        if loss<best_loss-1e-4:best_loss=loss; best=copy.deepcopy(net); stale=0\n        else:stale+=1\n        if stale>=6:break\n    parameters=sum(v.size for v in best.coefs_+best.intercepts_)\n    return dict(network=best,scaler=scaler,history=history,parameters=parameters,\n                fit_indices=fit,stop_indices=stop,fit_pairs=len(fy),stop_pairs=len(ey))\n\n\ndef pair_scores(model,x,a,c,batch=512):\n    result=[]\n    for start in range(0,len(a),batch):\n        f=pair_features(x,a[start:start+batch],c[start:start+batch])\n        z=np.clip(model[\'scaler\'].transform(f),-6,6)\n        result.append(model[\'network\'].predict_proba(z)[:,1])\n    return np.concatenate(result) if result else np.array([])\n\n\ndef query_features(model,x,y,gallery,s,r):\n    """No query truth is used. Score every gallery photo of all 15 candidates."""\n    n=len(s[\'q\']); k=15; ids=s[\'c\'].ident.to_numpy().reshape(n,k)\n    blocks={name:gallery[y[gallery]==name] for name in np.unique(ids)}\n    aa=[]; cc=[]; sizes=[]\n    for i,query in enumerate(s[\'order\']):\n        for name in ids[i]:\n            g=blocks[name]; aa.extend([query]*len(g)); cc.extend(g); sizes.append(len(g))\n    pp=pair_scores(model,x,np.asarray(aa),np.asarray(cc)); statistics=[]; offset=0\n    for size in sizes:\n        v=np.sort(pp[offset:offset+size])[::-1]; offset+=size\n        statistics.append([v[0],v[:2].mean(),v[:3].mean(),v.mean(),(v>.5).mean()])\n    statistics=np.asarray(statistics).reshape(n,k,5)\n    count=np.asarray(sizes).reshape(n,k); top=r[\'pc\'].argmax(1); ix=np.arange(n)\n    get=lambda key:s[\'c\'][key].to_numpy().reshape(n,k)[ix,top]\n    sorted_pc=np.sort(r[\'pc\'],axis=1)\n    # The control and MLP arm have identical baseline context and calibration model.\n    context=np.c_[r[\'pn\'],r[\'pb\'],np.clip(1-r[\'raw\'].sum(1),0,1),sorted_pc[:,-1],sorted_pc[:,-2],\n        -(r[\'pc\']*np.log(np.maximum(r[\'pc\'],1e-12))).sum(1),np.log1p(count[ix,top]),\n        get(\'mxr\'),get(\'mxl\'),np.log1p(get(\'sx\')),np.log1p(get(\'n_flank\')),\n        np.log1p(get(\'n_view\')),s[\'q\'].sp.to_numpy(),s[\'q\'].view.to_numpy()<0]\n    sorted_best=np.sort(statistics[:,:,0],axis=1)\n    richest=statistics[:,:,0].argmax(1)\n    extra=np.c_[statistics[ix,top],statistics.max(1),\n        (statistics*r[\'pc\'][:,:,None]).sum(1),sorted_best[:,-1]-sorted_best[:,-2],\n        np.log1p(count[ix,richest]),np.log1p(count.sum(1))]\n    return np.nan_to_num(context),np.nan_to_num(np.c_[context,extra])\n\n\ndef calibrator(features,unknown):\n    # Query probabilities are learned on separate calibration identities;\n    # pair scores themselves are never treated as calibrated P(known).\n    return make_pipeline(StandardScaler(),LogisticRegression(C=.1,max_iter=1000)).fit(features,unknown)\n\n\ndef rank(candidates,pc,pnew):\n    labels=np.c_[candidates,np.full(len(pc),\'new_individual\',dtype=object)]\n    scores=np.c_[(1-pnew[:,None])*pc,pnew]\n    return np.take_along_axis(labels,np.argsort(-scores,axis=1)[:,:5],axis=1)\n\n\ndef rr5(pred,truth):\n    return np.array([next((1/(i+1) for i,label in enumerate(row) if label==target),0.) for row,target in zip(pred,truth)])\n'}
exec(RECOVERY_SOURCE)
